[
  {"description": "List every attribute (type, residency, ADS name, size) of one sample $MFT record.",
   "sql": "SELECT entry, type_name, resident, name, logical_size FROM mft.main.attributes((FROM (SELECT content AS blob, 22::UBIGINT AS entry FROM read_blob('https://raw.githubusercontent.com/Query-farm/vgi-mft/v0.2.0/data/sample.mft'))))"},
  {"description": "Profile the attribute makeup of a whole $MFT: feed every record entry from the read_mft timeline into attributes(), label each attribute type with its purpose from the ntfs_attribute_types reference view, and count the records and attribute instances per type.",
   "sql": "SET VARIABLE mft_sample = (SELECT content FROM read_blob('https://raw.githubusercontent.com/Query-farm/vgi-mft/v0.2.0/data/sample.mft'));\nSELECT a.type_id, t.type_name, t.purpose, count(DISTINCT a.entry) AS records, count(*) AS instances FROM mft.main.attributes((FROM (SELECT getvariable('mft_sample') AS blob, entry FROM mft.main.read_mft(getvariable('mft_sample'))))) AS a JOIN mft.main.ntfs_attribute_types AS t ON t.type_id = a.type_id GROUP BY ALL ORDER BY a.type_id"}
]

