  {"description": "Reconstruct the full filesystem path of one record (entry 20) in the sample $MFT.",
   "sql": "SELECT mft.main.full_path((SELECT content FROM read_blob('https://raw.githubusercontent.com/Query-farm/vgi-mft/v0.2.0/data/sample.mft')), 20) AS full_path"}
]

[
  {"description": "Fully decode one sample $MFT record, exposing its primary name and how many alternate data streams it carries.",
   "sql": "SELECT r.fn[1].name AS primary_name, len(r.ads) AS ads_count FROM (SELECT mft.main.mft_record((SELECT content FROM read_blob('https://raw.githubusercontent.com/Query-farm/vgi-mft/v0.2.0/data/sample.mft')), 22) AS r)"},
  {"description": "Pair each path in the read_mft timeline with its DOS 8.3 short name, unnesting the full $FILE_NAME list that mft_record() decodes for the entry (the timeline keeps only the primary Win32 name).",
   "sql": "SET VARIABLE mft_sample = (SELECT content FROM read_blob('https://raw.githubusercontent.com/Query-farm/vgi-mft/v0.2.0/data/sample.mft'));\nSELECT t.full_path, f.name AS short_name FROM mft.main.read_mft(getvariable('mft_sample')) AS t, unnest(mft.main.mft_record(getvariable('mft_sample'), t.entry).fn) AS u(f) WHERE f.namespace = 'DOS' ORDER BY t.full_path"}
]

